"use client";

import { useState } from "react";

type LeadCaptureFormProps = {
  nameLabel: string;
  emailLabel: string;
  companyLabel: string;
  focusLabel: string;
  focusOptions: string[];
  intro: string;
  note: string;
  buttonLabel: string;
  successTitle: string;
  successMessage: string;
  sendAnotherLabel: string;
  submittingLabel: string;
  genericErrorMessage: string;
  invalidEmailMessage: string;
  missingFieldsMessage: string;
};

type FormState = {
  status: "idle" | "submitting" | "success" | "error";
  message?: string;
};

const initialState: FormState = {
  status: "idle",
};

export function LeadCaptureForm({
  nameLabel,
  emailLabel,
  companyLabel,
  focusLabel,
  focusOptions,
  intro,
  note,
  buttonLabel,
  successTitle,
  successMessage,
  sendAnotherLabel,
  submittingLabel,
  genericErrorMessage,
  invalidEmailMessage,
  missingFieldsMessage,
}: LeadCaptureFormProps) {
  const [state, setState] = useState<FormState>(initialState);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const form = event.currentTarget;
    const formData = new FormData(form);

    setState({ status: "submitting" });

    const response = await fetch("/api/lead", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        name: formData.get("name"),
        email: formData.get("email"),
        company: formData.get("company"),
        focus: formData.get("focus"),
        website: formData.get("website"),
      }),
    });

    if (!response.ok) {
      const payload = (await response.json().catch(() => null)) as { errorCode?: string } | null;
      const message =
        payload?.errorCode === "invalid_email"
          ? invalidEmailMessage
          : payload?.errorCode === "missing_required"
            ? missingFieldsMessage
            : genericErrorMessage;
      setState({
        status: "error",
        message,
      });
      return;
    }

    form.reset();
    setState({
      status: "success",
      message: successMessage,
    });
  }

  return (
    <div className="rounded-[28px] border border-[#d8d0c3] bg-[linear-gradient(180deg,#fbf8f3_0%,#f5f0e7_100%)] p-5 shadow-[0_20px_46px_rgba(35,29,23,0.14)] md:p-7">
      <p className="max-w-[64ch] text-[14px] leading-[1.75] text-[#3f3831]/80 md:text-[15px]">{intro}</p>

      {state.status === "success" ? (
        <div className="mt-6 space-y-3" aria-live="polite">
          <p className="font-medium text-[#1f1a16]">{successTitle}</p>
          <p className="text-[14px] leading-relaxed text-[#3d372f]/75">{state.message}</p>
          <button
            type="button"
            className="animated-link text-sm text-[#5e3a21]"
            onClick={() => setState(initialState)}
          >
            {sendAnotherLabel}
          </button>
        </div>
      ) : (
        <form className="mt-6 grid gap-4 md:gap-5" onSubmit={handleSubmit}>
          <input
            name="website"
            type="text"
            tabIndex={-1}
            autoComplete="off"
            className="hidden"
            aria-hidden="true"
          />

          <label className="grid gap-2 text-[13px] font-medium text-[#3c362f]/78">
            {nameLabel}
            <input
              name="name"
              type="text"
              required
              autoComplete="name"
              className="h-12 rounded-[14px] border border-[#d9d0c3] bg-white/78 px-4 text-[16px] text-[#1e1915] outline-none transition-colors focus:border-[#ac8f78]"
            />
          </label>

          <label className="grid gap-2 text-[13px] font-medium text-[#3c362f]/78">
            {emailLabel}
            <input
              name="email"
              type="email"
              required
              autoComplete="email"
              className="h-12 rounded-[14px] border border-[#d9d0c3] bg-white/78 px-4 text-[16px] text-[#1e1915] outline-none transition-colors focus:border-[#ac8f78]"
            />
          </label>

          <label className="grid gap-2 text-[13px] font-medium text-[#3c362f]/78">
            {companyLabel}
            <input
              name="company"
              type="text"
              autoComplete="organization"
              className="h-12 rounded-[14px] border border-[#d9d0c3] bg-white/78 px-4 text-[16px] text-[#1e1915] outline-none transition-colors focus:border-[#ac8f78]"
            />
          </label>

          <label className="grid gap-2 text-[13px] font-medium text-[#3c362f]/78">
            {focusLabel}
            <select
              name="focus"
              defaultValue={focusOptions[0]}
              className="h-12 rounded-[14px] border border-[#d9d0c3] bg-white/78 px-4 text-[16px] text-[#1e1915] outline-none transition-colors focus:border-[#ac8f78]"
            >
              {focusOptions.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </select>
          </label>

          <div className="mt-2 flex flex-col-reverse gap-4 sm:flex-row sm:items-center sm:justify-between">
            <p className="text-[12px] leading-relaxed text-[#3f3831]/62">{note}</p>
            <button
              type="submit"
              disabled={state.status === "submitting"}
              className="w-full rounded-full border border-[#c2b39f] bg-[#1f1a16] px-5 py-2.5 text-base font-medium text-[#f7f3eb] transition hover:bg-[#2b241f] sm:w-auto disabled:cursor-not-allowed disabled:opacity-60"
            >
              {state.status === "submitting" ? submittingLabel : buttonLabel}
            </button>
          </div>

          {state.status === "error" ? (
            <p className="text-sm text-[#7b3c31]" aria-live="polite">
              {state.message}
            </p>
          ) : null}
        </form>
      )}
    </div>
  );
}
